    benefit: { en: "Long-term credit to state cooperative banks and RRBs at concessional rates for lending to primary agricultural credit societies.", hi: "राज्य सहकारी बैंकों और RRBs को प्राथमिक कृषि सहकारी समितियों को ऋण देने के लिए रियायती दरों पर दीर्घकालिक ऋण।", gu: "પ્રાથમિક ખેતી સહકારી સમિતિઓને ધિરાણ આપવા માટે રાજ્ય સહકારી બેંકો અને RRBs ને રિયાયતી દરે દીર્ઘકાલીન ધિરાણ." },
    overview: { en: "NRCF is refinanced by NABARD to state cooperative banks and regional rural banks for lending to PACS, FPOs, and cooperatives at concessional rates.", hi: "NRCF को NABARD द्वारा राज्य सहकारी बैंकों और क्षेत्रीय ग्रामीण बैंकों को PACS, FPO और सहकारी समितियों को रियायती दरों पर ऋण देने के लिए पुनर्वित्तपोषित किया जाता है।", gu: "NRCF ને NABARD દ્વારા PACS, FPO અને સહકારી સંસ્થાઓને રિયાયતી દરે ધિરાણ આપવા માટે રાજ્ય સહકારી બેંકો અને પ્રાદેશિક ગ્રામીણ બેંકોને પુનર્વિત્ત આપવામાં આવે છે." },
    eligibility: { en: ["State Cooperative Banks (SCBs)", "District Central Cooperative Banks (DCCBs)", "Regional Rural Banks (RRBs)"], hi: ["राज्य सहकारी बैंक (SCB)", "जिला केंद्रीय सहकारी बैंक (DCCB)", "क्षेत्रीय ग्रामीण बैंक (RRB)"], gu: ["રાજ્ય સહકારી બેંક (SCB)", "જિલ્લા કેન્દ્રીય સહકારી બેંક (DCCB)", "પ્રાદેશિક ગ્રામીણ બેંક (RRB)"] },
    benefits: { en: ["Concessional refinance from NABARD at lower interest rates.", "Funds available for short-term, medium-term, and long-term lending."], hi: ["NABARD से कम ब्याज दरों पर रियायती पुनर्वित्त।", "अल्पकालिक, मध्यमकालिक और दीर्घकालिक ऋण के लिए धन उपलब्ध।"], gu: ["NABARD તરફથી ઓછા વ્યાજ દરે રિયાયતી પુનર્વિત્ત.", "અલ્પકાલીન, મધ્યકાલીન અને દીર્ઘકાલીન ધિરાણ માટે ભંડોળ ઉપલબ્ધ."] },
    howToApply: { en: ["Contact your State Cooperative Bank or DCCB.", "Apply through NABARD online portal."], hi: ["अपने राज्य सहकारी बैंक या DCCB से संपर्क करें।", "NABARD ऑनलाइन पोर्टल के माध्यम से आवेदन करें।"], gu: ["તમારી રાજ્ય સહકારી બેંક અથવા DCCB નો સંપર્ક કરો.", "NABARD ઑનલાઇન પોર્ટલ દ્વારા અરજી કરો."] },
    documents: { en: ["Aadhaar card", "PAN card", "Bank account details", "Cooperative registration certificate"], hi: ["आधार कार्ड", "पैन कार्ड", "बैंक खाता विवरण", "सहकारी पंजीकरण प्रमाणपत्र"], gu: ["આધાર કાર્ડ", "PAN કાર્ડ", "બેંક ખાતાની વિગતો", "સહકારી નોંધણી પ્રમાણપત્ર"] },
